 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/byteorder.h>

#include "max17048.h"

LOG_MODULE_REGISTER(max17048_emul, CONFIG_I2C_LOG_LEVEL);

#define DT_DRV_COMPAT maxim_max17048

/** Run-time data for the emulator */
struct max17048_emul_data {
	struct i2c_emul_data emul;
	uint16_t reg_vcell;
	uint16_t reg_soc;
	uint16_t reg_crate;
	uint16_t reg_version;
};

static int max17048_emul_read(const struct i2c_emul *emul, int reg, uint8_t *val, int bytes)
{
	struct max17048_emul_data *data =
		CONTAINER_OF(emul, struct max17048_emul_data, emul);

	if (bytes != 2) {
		LOG_ERR("MAX17048 emulator only supports 2-byte reads");
		return -EIO;
	}

	uint16_t reg_val;
	switch (reg) {
	case REGISTER_VCELL:
		reg_val = data->reg_vcell;
		break;
	case REGISTER_SOC:
		reg_val = data->reg_soc;
		break;
	case REGISTER_CRATE:
		reg_val = data->reg_crate;
		break;
	case REGISTER_VERSION:
		reg_val = data->reg_version;
		break;
	default:
		LOG_ERR("Attempted to read unsupported register 0x%02x", reg);
		return -EIO;
	}

	sys_put_be16(reg_val, val);
	return 0;
}

static int max17048_emul_transfer(const struct i2c_emul *emul, struct i2c_msg *msgs, int num_msgs)
{
	if (num_msgs == 0) {
		return 0;
	}

	/* The driver uses i2c_write_read_dt, which translates to two messages:
	 * 1. Write: register address (1 byte)
	 * 2. Read: data (2 bytes)
	 */
	if (num_msgs == 2 && (msgs[0].flags & I2C_MSG_RW_MASK) == I2C_MSG_WRITE &&
	    (msgs[1].flags & I2C_MSG_RW_MASK) == I2C_MSG_READ) {
		if (msgs[0].len != 1 || msgs[1].len != 2) {
			LOG_ERR("Unexpected message lengths: write %d, read %d",
				msgs[0].len, msgs[1].len);
			return -EIO;
		}
		return max17048_emul_read(emul, msgs[0].buf[0], msgs[1].buf, msgs[1].len);
	}

	LOG_ERR("Unsupported I2C transfer type (num_msgs: %d)", num_msgs);
	return -EIO;
}

void emul_max17048_set_crate_status(int value)
{
	const struct device *dev = DEVICE_DT_GET_ANY(maxim_max17048);
	const struct max17048_config *cfg = dev->config;
	struct i2c_emul_data *i2c_emul_data = i2c_emul_get_data(&cfg->i2c);
	struct max17048_emul_data *data =
		CONTAINER_OF(i2c_emul_data, struct max17048_emul_data, emul);

	data->reg_crate = (uint16_t)value;
}

static int max17048_emul_init(const struct emul *emul_dev,
			      const struct i2c_emul_cfg *cfg,
			      struct i2c_emul_data *i2c_emul_data)
{
	struct max17048_emul_data *data =
		CONTAINER_OF(i2c_emul_data, struct max17048_emul_data, emul);

	/* Default values for registers */
	data->reg_vcell = 0x1000; /* Example voltage */
	data->reg_soc = 0x6400;   /* 100% (100 * 256) */
	data->reg_crate = 0x4000; /* Example charge rate (positive for charging) */
	data->reg_version = 0x0010; /* Expected version */

	return 0;
}

static const struct i2c_emul_api max17048_emul_api = {
	.transfer = max17048_emul_transfer,
};

#define MAX17048_EMUL_DEFINE(inst)                                                                 \
	static struct max17048_emul_data max17048_emul_data_##inst;                                \
	static const struct i2c_emul_cfg max17048_emul_cfg_##inst = {                              \
		.i2c_label = DT_INST_BUS_LABEL(inst),                                              \
		.dev_label = DT_LABEL(DT_DRV_INST(inst)),                                         \
		.addr = DT_INST_REG_ADDR(inst),                                                    \
	};                                                                                         \
	EMUL_DEFINE(max17048_emul_data_##inst, max17048_emul_init, &max17048_emul_cfg_##inst,      \
			&max17048_emul_api, &max17048_emul_data_##inst.emul);

DT_INST_FOREACH_STATUS_OKAY(MAX17048_EMUL_DEFINE)
